#!/usr/bin/env python3
"""Apply reviewed dark/light retirement and LF preference to the installed profile."""
import base64,hashlib,json,os,shutil,subprocess,sys,tempfile,zlib
from pathlib import Path
PAYLOAD=''
PIN='a189759bb5585984e3f5eb5ca959ef7b2651f9ed49d6f05a43bb334293235e7a'
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def require(ok,msg):
 if not ok:raise RuntimeError(msg)
def apply(config,rows,work):
 actions=[]
 for row in rows:
  rel=row['path'];require(not Path(rel).is_absolute() and '..' not in Path(rel).parts,'Unsafe payload path')
  p=config/rel
  require(not any(x.is_symlink() for x in [p,*list(p.parents)[:-1]]),'Symlink update destination: '+rel)
  current=sha(p) if p.is_file() else None
  if current==row['after']:continue
  require(current==row['before'],'Changed user file preserved: '+rel)
  actions.append(row)
 for row in actions:
  p=config/row['path'];backup=work/'backup'/row['path'];backup.parent.mkdir(parents=True,exist_ok=True);shutil.copy2(p,backup)
 done=[]
 try:
  for row in actions:
   p=config/row['path'];require(sha(p)==row['before'],'Destination changed during update')
   if row['data'] is None:
    retired=work/'retired'/row['path'];retired.parent.mkdir(parents=True,exist_ok=True);p.rename(retired)
   else:
    raw=base64.b64decode(row['data']);require(hashlib.sha256(raw).hexdigest()==row['after'],'Payload file mismatch')
    fd,name=tempfile.mkstemp(prefix='.gup-update-',dir=p.parent)
    with os.fdopen(fd,'wb') as f:f.write(raw);f.flush();os.fsync(f.fileno())
    Path(name).chmod(p.stat().st_mode & 0o777);os.replace(name,p)
   done.append(row)
 except BaseException as error:
  for row in reversed(done):
   p=config/row['path'];current=sha(p) if p.is_file() else None
   if current!=row['after']:raise RuntimeError('Update failed; changed destination preserved: '+str(error)) from error
   shutil.copy2(work/'backup'/row['path'],p)
  raise
 return [r['path'] for r in actions]
def main():
 require(os.geteuid()!=0,'Run as your desktop user')
 home=Path.home();config=home/'.config'
 require(os.environ.get('XDG_CONFIG_HOME',str(config))==str(config),'Custom config root requires review')
 raw=zlib.decompress(base64.b64decode(PAYLOAD));require(hashlib.sha256(raw).hexdigest()==PIN,'Embedded payload mismatch');rows=json.loads(raw)
 state=home/'.local/state/gup-r7';state.mkdir(parents=True,exist_ok=True);os.umask(0o077)
 work=Path(tempfile.mkdtemp(prefix='retire-darklight-',dir=state));changed=apply(config,rows,work)
 report={'status':'APPLIED','changed':changed,'backup':str(work),'lf_available':shutil.which('lf') is not None,'certification':'NOT_CERTIFIED'}
 for args in [['hyprctl','reload'],['pkill','-SIGUSR2','-u',str(os.getuid()),'-x','waybar']]:
  p=subprocess.run(args,capture_output=True,text=True,timeout=20);report[' '.join(args)]={'exit':p.returncode,'reply':p.stdout.strip(),'stderr':p.stderr.strip()}
 (work/'report.json').write_text(json.dumps(report,indent=2)+'\n');print(json.dumps(report,indent=2))
 if not report['lf_available']:print('LF binding is configured; LF executable is not currently on PATH.')
 return 0
if __name__=='__main__':
 try:sys.exit(main())
 except (OSError,ValueError,RuntimeError) as e:print('Stopped: '+str(e),file=sys.stderr);sys.exit(1)
